{
  "definition_simple": "在比赛或竞争中取得胜利。",
  "definition_standard": "指在竞赛、战争、诉讼等对抗性活动中战胜对手，取得成功或胜利。",
  "pos": "动词",
  "semantic_class": "action",
  "sentences": [
    {
      "tier": "T1",
      "sentence": "我们队这场比赛获胜了。"
    },
    {
      "tier": "T1",
      "sentence": "他们希望能在决赛中获胜。"
    },
    {
      "tier": "T2",
      "sentence": "经过艰苦的努力，他终于获胜了。"
    },
    {
      "tier": "T2",
      "sentence": "这场胜利使我们获得了获胜的机会。"
    },
    {
      "tier": "T3",
      "sentence": "凭借出色的战术，客队最终取得了获胜。"
    },
    {
      "tier": "T3",
      "sentence": "在关键时刻保持冷静是获胜的关键。"
    },
    {
      "tier": "T4",
      "sentence": "由于对手的失误，我方顺利地拿下了这场获胜。"
    },
    {
      "tier": "T4",
      "sentence": "这场辩论赛的获胜需要充分的准备和敏捷的思维。"
    },
    {
      "tier": "T5",
      "sentence": "面对强大的对手，全队上下团结一心，最终艰难地赢得了获胜。"
    },
    {
      "tier": "T6",
      "sentence": "在逐鹿中原的漫长历史进程中，唯有战略宏远者方能立于不败之地并最终获胜。"
    }
  ],
  "morphological_forms": [],
  "morphology_wrong_forms": [],
  "l1_audio_confusables": [
    {
      "word": "获生",
      "explanation": "拼音同为 huòshēng，但“获生”意为获得生还或新生，与比赛获胜无关。"
    },
    {
      "word": "货声",
      "explanation": "发音相近（huòshēng），但“货声”在汉语中不是常用词，属于无意义的声旁误读。"
    },
    {
      "word": "霍生",
      "explanation": "发音类似（huòshēng），通常用作人名或译音，无比赛胜利的意思。"
    }
  ],
  "primary_collocate": "赢得获胜",
  "collocation_distractors": [
    {
      "word": "获得胜利",
      "explanation": "“获得”与“胜利”搭配更自然，而“获得获胜”语义重复。"
    },
    {
      "word": "取得成功",
      "explanation": "“成功”是抽象名词，虽然常与“获胜”对比，但不能直接作为“获胜”的宾语搭配。"
    },
    {
      "word": "打败敌人",
      "explanation": "这是动宾短语，侧重于动作施加的对象，而不是与“获胜”形成固定词组。"
    }
  ],
  "collocation_wrong_collocate": "获取获胜",
  "cloze_distractors": [
    {
      "word": "成功",
      "explanation": "“成功”是形容词或名词，而句子语法位置需要动词，且语义上“成功”泛指达成目标，不如“获胜”精确。"
    },
    {
      "word": "失败",
      "explanation": "“失败”与句子的积极语境完全相反，属于反义词干扰。"
    },
    {
      "word": "比赛",
      "explanation": "“比赛”是名词或动词，放入该句会导致动宾结构或主谓结构混乱。"
    }
  ],
  "discrimination_wrong_sentences": [
    {
      "sentence": "他在这次考试中获胜了第一名。",
      "reason": "“获胜”通常用于对抗性的比赛或竞技，考试取得第一名通常用“夺得”或“取得”，不能直接说“考试获胜”。"
    },
    {
      "sentence": "这家公司在市场竞争中获胜了他们的竞争对手。",
      "reason": "“获胜”是不及物动词或带有较少宾语的动词，不能直接带人或公司作为直接宾语，应改为“战胜了他们的竞争对手”。"
    },
    {
      "sentence": "昨天的天气非常获胜。",
      "reason": "“获胜”是动词，不能作形容词去修饰或描述天气状况。"
    }
  ],
  "spot_incorrect": {
    "sentence": "经过加时赛，我们终于成功地获胜了冠军。",
    "error_description": "“获胜”是不及物动词，不能直接带宾语“冠军”；应改为“赢得了冠军”或“取得了胜利”。",
    "corrected_version": "经过加时赛，我们终于成功地赢得了冠军。"
  },
  "word_family_forms": [
    "获胜者"
  ],
  "word_family_fake_forms": [
    "获胜性",
    "获胜化",
    "获胜然"
  ],
  "syn_ant_candidates": [
    {
      "word": "取胜",
      "type": "synonym"
    },
    {
      "word": "获捷",
      "type": "synonym"
    },
    {
      "word": "失败",
      "type": "antonym"
    },
    {
      "word": "战败",
      "type": "antonym"
    }
  ],
  "particle_candidates": []
}
